<?php

/**
 * Imports a site with one generated GridFS file of <megabytes> MiB into an SQLite database and an
 * upload directory under <directory>, for MongoImporterTest::testAFileLargerThanTheMemoryLimitIsImported,
 * which runs it with a memory limit smaller than the file. Prints the file counts, where the file is,
 * the md5 of the generated bytes and the peak memory, as JSON.
 *
 * php import_large_file.php <directory> <megabytes>
 */

if (PHP_SAPI !== 'cli' && PHP_SAPI !== 'phpdbg') {
    http_response_code(404);
    exit;
}

require dirname(__DIR__, 4) . '/vendor/autoload.php';

if ($argc !== 3 || !is_dir($argv[1])) {
    fwrite(STDERR, "Usage: php import_large_file.php <directory> <megabytes>\n");
    exit(2);
}
$directory = $argv[1];
$megabytes = (int) $argv[2];

$piece = str_repeat('0123456789abcdef', 65536);
$md5 = hash_init('md5');
for ($i = 0; $i < $megabytes; ++$i) {
    hash_update($md5, $piece);
}
$md5 = hash_final($md5);
$id = '6aff2dc3a96cd4f90409ffff';

$source = (new \Tests\Unit\Upgrade\Mongo\ArrayMongoSource())
    ->add('config', ['_id' => '6aff2dc3a96cd4f90409fffe', 'title' => 'Large'])
    ->addFile(
        ['_id' => $id, 'length' => $megabytes * strlen($piece), 'md5' => $md5, 'filename' => 'large.bin', 'metadata' => ['mime_type' => 'application/octet-stream']],
        static fn () => \Idno\Upgrade\Mongo\ChunkStream::open((static function () use ($piece, $megabytes): \Generator {
            for ($i = 0; $i < $megabytes; ++$i) {
                yield $piece;
            }
        })()),
    );
unset($piece);

$target = \Tests\Storage\PrivateDatabase::sqliteFile($directory . '/large.sqlite', migrate: false);
$filesystem = \Idno\Storage\Files\FilesystemFactory::fromConfig(['uploadpath' => $directory . '/uploads/']);
$files = new \Idno\Storage\Files\FileStore($filesystem, 'example.com');
$result = (new \Idno\Upgrade\Mongo\MongoImporter($source, $target, $files, new \Psr\Log\NullLogger()))->run(static function (string $line): void {
});
$target->close();

echo json_encode([
    'files' => $result['files'],
    'path' => $directory . '/uploads/' . $files->path($id),
    'md5' => $md5,
    'peak' => memory_get_peak_usage(true),
]);
